import java.util.List;

/**
 * Aggregated report returned by the validation service,
 * mirroring WS-READ / WS-CLEAN / WS-FLAGGED counters.
 */
public class ValidationRunReport {

    private final int recordsRead;
    private final int recordsClean;
    private final int recordsFlagged;
    private final List<ValidationResult> flaggedResults;

    public ValidationRunReport(int recordsRead, int recordsClean,
                               int recordsFlagged, List<ValidationResult> flaggedResults) {
        this.recordsRead = recordsRead;
        this.recordsClean = recordsClean;
        this.recordsFlagged = recordsFlagged;
        this.flaggedResults = flaggedResults;
    }

    public int getRecordsRead() { return recordsRead; }
    public int getRecordsClean() { return recordsClean; }
    public int getRecordsFlagged() { return recordsFlagged; }
    public List<ValidationResult> getFlaggedResults() { return flaggedResults; }
}

