package com.example.validate.service;

import com.example.validate.dto.ValidationResult;
import com.example.validate.model.Employee;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.util.Set;

/**
 * Encapsulates all business/policy checks that were in the COBOL CHECK-RECORD
 * and LOG-ISSUE paragraphs.
 *
 * Business rules preserved verbatim:
 *   1. EMP-ID must be numeric and non-zero
 *   2. EMP-NAME must not be blank
 *   3. EMP-DEPT must be one of: IT, HR, SALES, FINANCE, OPERATIONS
 *   4. EMP-SALARY must be >= 30 000.00 (WS-MIN-WAGE)
 *   5. EMP-HIRE-DATE must be a valid calendar date
 *   6. EMP-AGE must be in [18, 70] inclusive
 */
@Service
public class EmployeeValidatorService {

    /** Mirrors WS-MIN-WAGE PIC 9(07)V99 VALUE 30000.00 */
    private static final BigDecimal MIN_WAGE = new BigDecimal("30000.00");

    /** Mirrors the department literals in CHECK-RECORD */
    private static final Set<String> VALID_DEPARTMENTS =
            Set.of("IT", "HR", "SALES", "FINANCE", "OPERATIONS");

    /**
     * Validates one employee record and returns a {@link ValidationResult}
     * containing every issue found (one issue per PERFORM LOG-ISSUE call).
     */
    public ValidationResult validate(Employee emp) {
        // Mirrors: MOVE EMP-ID TO ERR-ID / MOVE EMP-NAME TO ERR-NAME
        ValidationResult result = new ValidationResult(emp.getEmpId(), emp.getEmpName());

        // --- Rule 1: INVALID EMPLOYEE ID ---
        // COBOL: IF EMP-ID IS NOT NUMERIC OR EMP-ID = 0
        // In Java the JPA mapping guarantees numeric type; null or zero are the failure cases.
        if (emp.getEmpId() == null || emp.getEmpId() == 0L) {
            result.addIssue("INVALID EMPLOYEE ID");
        }

        // --- Rule 2: MISSING NAME ---
        // COBOL: IF EMP-NAME = SPACES
        if (emp.getEmpName() == null || emp.getEmpName().isBlank()) {
            result.addIssue("MISSING NAME");
        }

        // --- Rule 3: UNKNOWN DEPARTMENT ---
        // COBOL: IF EMP-DEPT NOT = "IT" AND NOT = "HR" AND ...
        if (emp.getEmpDept() == null
                || !VALID_DEPARTMENTS.contains(emp.getEmpDept().trim().toUpperCase())) {
            result.addIssue("UNKNOWN DEPARTMENT");
        }

        // --- Rule 4: SALARY BELOW MINIMUM ---
        // COBOL: IF EMP-SALARY < WS-MIN-WAGE
        if (emp.getEmpSalary() == null
                || emp.getEmpSalary().compareTo(MIN_WAGE) < 0) {
            result.addIssue("SALARY BELOW 30,000 POLICY MINIMUM");
        }

        // --- Rule 5: INVALID HIRE DATE ---
        // COBOL: FUNCTION TEST-DATE-YYYYMMDD(WS-DATE-NUM) NOT = 0
        // PostgreSQL / JPA enforces date validity at the DB level; a null value
        // here means the record arrived without a parseable date.
        if (emp.getEmpHireDate() == null) {
            result.addIssue("INVALID HIRE DATE");
        }

        // --- Rule 6: AGE OUTSIDE RANGE ---
        // COBOL: IF EMP-AGE < 18 OR EMP-AGE > 70
        if (emp.getEmpAge() == null
                || emp.getEmpAge() < 18
                || emp.getEmpAge() > 70) {
            result.addIssue("AGE OUTSIDE 18-70 RANGE");
        }

        return result;
    }
}

