package com.example.validate.service;

import com.example.validate.dto.ValidationResult;
import com.example.validate.dto.ValidationRunReport;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.io.BufferedWriter;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;

/**
 * Writes the text-based validation report to data/output/validation.rpt,
 * reproducing the exact line format of the COBOL RPT-FILE output:
 *
 *   EMPLOYEE DATA VALIDATION REPORT
 *   ----------------------------------------------------------------------
 *   NNNNN  NNNNNNNNNNNNNNNNNNNN MMMMMMMMMMMMMMMMMMMMMMMMMMMMMMMMMMMMMMMM
 *   ...
 *   ----------------------------------------------------------------------
 *   RECORDS READ:           NNN
 *   RECORDS CLEAN:          NNN
 *   RECORDS FLAGGED:        NNN
 */
@Service
public class ReportWriterService {

    private static final String SEP_LINE = "-".repeat(70);
    private static final String REPORT_HEADER = "EMPLOYEE DATA VALIDATION REPORT";

    @Value("${validate.report.output-path:data/output/validation.rpt}")
    private String outputPath;

    public void writeReport(ValidationRunReport report) {
        Path path = Paths.get(outputPath);
        try {
            Files.createDirectories(path.getParent());
        } catch (IOException e) {
            throw new UncheckedIOException("Cannot create output directory", e);
        }

        try (BufferedWriter writer = Files.newBufferedWriter(path)) {

            // WRITE RPT-LINE (header)
            writeLine(writer, REPORT_HEADER);
            // WRITE RPT-LINE FROM SEP-LINE
            writeLine(writer, SEP_LINE);

            // One line per issue, mirroring WRITE RPT-LINE FROM ERR-LINE inside LOG-ISSUE
            for (ValidationResult vr : report.getFlaggedResults()) {
                for (String issue : vr.getIssues()) {
                    // ERR-LINE: EMP-ID(9(05)) + 2 spaces + EMP-NAME(X(20)) + 1 space + ERR-MSG(X(40))
                    String line = String.format("%-5d  %-20s %-40s",
                            vr.getEmpId() != null ? vr.getEmpId() : 0L,
                            truncate(vr.getEmpName(), 20),
                            truncate(issue, 40));
                    writeLine(writer, line);
                }
            }

            // WRITE RPT-LINE FROM SEP-LINE
            writeLine(writer, SEP_LINE);

            // Summary lines: SUM-LABEL(X(24)) + SUM-COUNT(ZZ9)
            writeLine(writer, summaryLine("RECORDS READ:",    report.getRecordsRead()));
            writeLine(writer, summaryLine("RECORDS CLEAN:",   report.getRecordsClean()));
            writeLine(writer, summaryLine("RECORDS FLAGGED:", report.getRecordsFlagged()));

        } catch (IOException e) {
            throw new UncheckedIOException("Failed to write validation report", e);
        }
    }

    // Mirrors SUM-LABEL (X(24)) + SUM-COUNT (ZZ9 = 3-digit, leading-space suppressed)
    private String summaryLine(String label, int count) {
        return String.format("%-24s%3d", label, count);
    }

    private void writeLine(BufferedWriter writer, String line) throws IOException {
        writer.write(line);
        writer.newLine();
    }

    private String truncate(String value, int maxLen) {
        if (value == null) return "";
        return value.length() > maxLen ? value.substring(0, maxLen) : value;
    }
}

