package com.example.validate.service;

import com.example.validate.dto.ValidationResult;
import com.example.validate.dto.ValidationRunReport;
import com.example.validate.model.Employee;
import com.example.validate.model.ValidationIssue;
import com.example.validate.model.ValidationSummary;
import com.example.validate.repository.EmployeeRepository;
import com.example.validate.repository.ValidationIssueRepository;
import com.example.validate.repository.ValidationSummaryRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;

/**
 * Orchestrates the full validation run, faithfully reproducing the COBOL
 * MAIN-PARA control flow:
 *
 *   OPEN INPUT/OUTPUT
 *   Write header + separator
 *   PERFORM UNTIL END-OF-FILE
 *       READ  ->  CHECK-RECORD
 *   END-PERFORM
 *   Write separator + summary
 *   CLOSE files
 *   DISPLAY final counts
 */
@Service
public class ValidationOrchestrationService {

    private static final Logger log = LoggerFactory.getLogger(ValidationOrchestrationService.class);

    private final EmployeeRepository employeeRepository;
    private final ValidationIssueRepository issueRepository;
    private final ValidationSummaryRepository summaryRepository;
    private final EmployeeValidatorService validatorService;
    private final ReportWriterService reportWriterService;

    public ValidationOrchestrationService(
            EmployeeRepository employeeRepository,
            ValidationIssueRepository issueRepository,
            ValidationSummaryRepository summaryRepository,
            EmployeeValidatorService validatorService,
            ReportWriterService reportWriterService) {
        this.employeeRepository = employeeRepository;
        this.issueRepository = issueRepository;
        this.summaryRepository = summaryRepository;
        this.validatorService = validatorService;
        this.reportWriterService = reportWriterService;
    }

    /**
     * Main entry point – mirrors MAIN-PARA + CHECK-RECORD.
     * Reads ALL employees from PostgreSQL (replaces file READ loop),
     * validates each one, persists issues, writes the flat-file report,
     * and persists the run summary.
     */
    @Transactional
    public ValidationRunReport runValidation() {

        // Mirrors: ADD 1 TO WS-READ / WS-CLEAN / WS-FLAGGED
        int wsRead    = 0;
        int wsClean   = 0;
        int wsFlagged = 0;

        List<ValidationResult> flaggedResults = new ArrayList<>();

        // Mirrors: PERFORM UNTIL END-OF-FILE ... READ EMP-FILE
        List<Employee> employees = employeeRepository.findAll();

        for (Employee emp : employees) {
            wsRead++;

            // Mirrors: PERFORM CHECK-RECORD
            ValidationResult result = validatorService.validate(emp);

            if (result.isClean()) {
                // Mirrors: ADD 1 TO WS-CLEAN
                wsClean++;
            } else {
                // Mirrors: ADD 1 TO WS-FLAGGED
                wsFlagged++;
                flaggedResults.add(result);

                // Persist each issue – mirrors WRITE RPT-LINE FROM ERR-LINE in LOG-ISSUE
                for (String issue : result.getIssues()) {
                    ValidationIssue entity = new ValidationIssue();
                    entity.setEmpId(emp.getEmpId());
                    entity.setEmpName(emp.getEmpName());
                    entity.setIssueMessage(issue);
                    entity.setCreatedAt(LocalDateTime.now());
                    issueRepository.save(entity);
                }
            }
        }

        ValidationRunReport report =
                new ValidationRunReport(wsRead, wsClean, wsFlagged, flaggedResults);

        // Mirrors: WRITE RPT-LINE (all output)
        reportWriterService.writeReport(report);

        // Persist run summary – mirrors the SUM-LINE block
        ValidationSummary summary = new ValidationSummary();
        summary.setRecordsRead(wsRead);
        summary.setRecordsClean(wsClean);
        summary.setRecordsFlagged(wsFlagged);
        summary.setRunAt(LocalDateTime.now());
        summaryRepository.save(summary);

        // Mirrors: DISPLAY "VALIDATE: " WS-FLAGGED " OF " WS-READ " RECORDS FLAGGED"
        log.info("VALIDATE: {} OF {} RECORDS FLAGGED", wsFlagged, wsRead);

        return report;
    }
}

