package com.example.validate.controller;

import com.example.validate.dto.ValidationRunReport;
import com.example.validate.model.ValidationIssue;
import com.example.validate.repository.ValidationIssueRepository;
import com.example.validate.service.ValidationOrchestrationService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;
import java.util.Map;

/**
 * REST surface for triggering a validation run and querying results.
 */
@RestController
@RequestMapping("/api/validation")
public class ValidationController {

    private final ValidationOrchestrationService orchestrationService;
    private final ValidationIssueRepository issueRepository;

    public ValidationController(ValidationOrchestrationService orchestrationService,
                                ValidationIssueRepository issueRepository) {
        this.orchestrationService = orchestrationService;
        this.issueRepository = issueRepository;
    }

    /**
     * POST /api/validation/run
     * Triggers a full validation run (equivalent to executing the COBOL program).
     */
    @PostMapping("/run")
    public ResponseEntity<Map<String, Object>> runValidation() {
        ValidationRunReport report = orchestrationService.runValidation();
        return ResponseEntity.ok(Map.of(
                "recordsRead",    report.getRecordsRead(),
                "recordsClean",   report.getRecordsClean(),
                "recordsFlagged", report.getRecordsFlagged()
        ));
    }

    /**
     * GET /api/validation/issues
     * Returns all persisted validation issues ordered by employee ID.
     */
    @GetMapping("/issues")
    public ResponseEntity<List<ValidationIssue>> getIssues() {
        return ResponseEntity.ok(issueRepository.findAllByOrderByEmpIdAsc());
    }
}

