package com.example.validate.runner;

import com.example.validate.service.ValidationOrchestrationService;
import org.springframework.boot.CommandLineRunner;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Component;

/**
 * Allows the validation to be run automatically at startup when
 * the "batch" Spring profile is active, mirroring the original
 * COBOL program's batch execution model.
 *
 * Activate with: --spring.profiles.active=batch
 */
@Component
@Profile("batch")
public class ValidationRunner implements CommandLineRunner {

    private final ValidationOrchestrationService orchestrationService;

    public ValidationRunner(ValidationOrchestrationService orchestrationService) {
        this.orchestrationService = orchestrationService;
    }

    @Override
    public void run(String... args) {
        orchestrationService.runValidation();
    }
}

