package com.example.validate.service;

import com.example.validate.dto.ValidationResult;
import com.example.validate.model.Employee;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.math.BigDecimal;
import java.time.LocalDate;

import static org.assertj.core.api.Assertions.assertThat;

class EmployeeValidatorServiceTest {

    private EmployeeValidatorService service;

    @BeforeEach
    void setUp() {
        service = new EmployeeValidatorService();
    }

    private Employee validEmployee() {
        Employee e = new Employee();
        e.setEmpId(10001L);
        e.setEmpName("Jane Doe");
        e.setEmpDept("IT");
        e.setEmpSalary(new BigDecimal("50000.00"));
        e.setEmpHireDate(LocalDate.of(2020, 6, 15));
        e.setEmpAge(30);
        return e;
    }

    @Test
    void cleanRecord_producesNoIssues() {
        ValidationResult result = service.validate(validEmployee());
        assertThat(result.isClean()).isTrue();
    }

    @Test
